def select_next_node(graph, unvisited_nodes):
    # Precomputed global feature
    bridge_high_bc = graph.graph['precomputed']['bridge_ratio_high_bc']

    nodes = unvisited_nodes
    # Extract node features
    betweenness = {n: graph.nodes[n]['betweenness'] for n in nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in nodes}
    core_num = {n: graph.nodes[n]['core_number'] for n in nodes}
    degree = {n: graph.nodes[n]['degree'] for n in nodes}

    # Normalize features to [0,1] to combine fairly
    def normalize(d):
        vals = list(d.values())
        min_v, max_v = min(vals), max(vals)
        if max_v - min_v < 1e-12:
            return {k:0 for k in d}
        return {k: (v - min_v)/(max_v - min_v) for k,v in d.items()}

    betweenness_n = normalize(betweenness)
    clustering_n = normalize(clustering)
    core_num_n = normalize(core_num)
    degree_n = normalize(degree)

    # Weights dynamically adjusted by bridge_ratio_high_bc (range assumed near [0,1])
    # Higher bridge_ratio_high_bc -> emphasize betweenness and core_number (targets bridges & cores)
    # Lower bridge_ratio_high_bc -> emphasize degree and inverse clustering (targets hubs, weakly clustered)
    w_bet = 0.5 * bridge_high_bc + 0.1
    w_core = 0.3 * bridge_high_bc + 0.1
    w_deg = 0.4 * (1 - bridge_high_bc) + 0.1
    w_clust = 0.3 * (1 - bridge_high_bc) + 0.1

    scores = {}
    for n in nodes:
        score = (
            w_bet * betweenness_n[n] + 
            w_core * core_num_n[n] + 
            w_deg * degree_n[n] + 
            w_clust * (1 - clustering_n[n])
        )
        scores[n] = score

    # Select node with highest combined score
    next_node = max(scores, key=scores.get)
    return next_node

import random
import networkx as nx

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph.get('precomputed', {})
    max_core_k = pre.get('max_core_k', 1)

    # Sampling a small subset of nodes to approximate closeness-like measure for efficiency
    sample_size = min(30, len(unvisited_nodes))
    sample_nodes = random.sample(unvisited_nodes, sample_size) if sample_size > 0 else []

    # Precompute shortest path lengths from each unvisited node to sampled nodes
    # To reduce complexity: do limited BFS from each node to sample_nodes or vice versa
    # Here we do BFS from sampled_nodes, then invert distances to get approx closeness
    dist_sums = {n: 0 for n in unvisited_nodes}
    reachable_counts = {n: 0 for n in unvisited_nodes}

    for s in sample_nodes:
        lengths = nx.single_source_shortest_path_length(graph, s, cutoff=10)
        for n in unvisited_nodes:
            if n in lengths:
                dist_sums[n] += lengths[n]
                reachable_counts[n] += 1

    # Avoid division by zero; closeness approx = inverse avg dist to samples
    closeness_approx = {}
    for n in unvisited_nodes:
        if reachable_counts[n] > 0 and dist_sums[n] > 0:
            closeness_approx[n] = reachable_counts[n] / dist_sums[n]
        else:
            closeness_approx[n] = 0.0

    # Normalize closeness approx to [0,1]
    vals = list(closeness_approx.values())
    min_v, max_v = min(vals), max(vals)
    if max_v - min_v < 1e-12:
        closeness_norm = {k: 0.0 for k in unvisited_nodes}
    else:
        closeness_norm = {k: (v - min_v)/(max_v - min_v) for k,v in closeness_approx.items()}

    # Extract and normalize clustering inverse
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    inv_clust = {n: 1 - clustering[n] for n in unvisited_nodes}
    c_vals = list(inv_clust.values())
    min_c, max_c = min(c_vals), max(c_vals)
    if max_c - min_c < 1e-12:
        inv_clust_norm = {k: 0.0 for k in unvisited_nodes}
    else:
        inv_clust_norm = {k: (v - min_c)/(max_c - min_c) for k,v in inv_clust.items()}

    # Normalize core number scaled by max_core_k
    core = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}
    # Scale core by max_core_k to [0,1]
    if max_core_k > 0:
        core_norm = {n: core[n]/max_core_k for n in unvisited_nodes}
    else:
        core_norm = {n: 0.0 for n in unvisited_nodes}

    # Dynamically scale core weight by global degree variance to balance impact
    degree_variance = pre.get('degree_variance', 1.0)
    w_core = min(0.7, max(0.1, degree_variance * 0.1))

    # Compute product score to emphasize nodes strong in all three aspects
    scores = {}
    for n in unvisited_nodes:
        scores[n] = closeness_norm[n] * inv_clust_norm[n] * (w_core * core_norm[n] + (1 - w_core))

    next_node = max(scores, key=scores.get)
    return next_node
